#!/usr/bin/env bash
set -euo pipefail
# GENERATED by dsl/gunbc/fleet_converge_timer_emit.dag (gunbc.fleet_converge_timer_emit). DO NOT HAND-EDIT.
# Idempotent per-host upsert: write service+timer units, daemon-reload, enable timer.
# The converge script self-selects via $(hostname -s); no SSH star required for steady-state.

svc_path="/etc/systemd/system/gunbc-fleet-converge.service"
timer_path="/etc/systemd/system/gunbc-fleet-converge.timer"
mkdir -p "$(dirname "$svc_path")"

cat > "$svc_path" <<'GUNBC_FLEET_CONVERGE_SERVICE_EOF'
[Unit]
Description=gunbc fleet converge (host-self-selecting reconcile)
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/bin/bash $HOME/ctrl/third_party/gunbc/.github/fleet-converge.sh
RemainAfterExit=no
GUNBC_FLEET_CONVERGE_SERVICE_EOF

cat > "$timer_path" <<'GUNBC_FLEET_CONVERGE_TIMER_EOF'
[Unit]
Description=gunbc fleet converge periodic reconcile

[Timer]
OnBootSec=2min
OnUnitActiveSec=600s
Unit=gunbc-fleet-converge.service

[Install]
WantedBy=timers.target
GUNBC_FLEET_CONVERGE_TIMER_EOF

systemctl daemon-reload
systemctl enable --now gunbc-fleet-converge.timer
printf 'fleet-converge-timer-receipt host=%s verdict=converged\n' "$(hostname -s 2>/dev/null || echo unknown)"
